"""Review fixed residual pilots, retain compact evidence and scientific sources."""
from pathlib import Path
import sys,json,hashlib,shutil,subprocess
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'experiments/residual-challengers-20261105'
WORK=ROOT/'work/novel-champion-20261105'
sys.path.insert(0,str(ROOT/'work/round2-plot-deps'))
import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt


def main():
    decision=json.loads((OUT/'decision.json').read_text());summary=pd.read_csv(OUT/'summary.csv').set_index('model');pairs=pd.read_csv(OUT/'development_portfolio_pairs.csv');base=summary.loc['champion']
    audit=json.loads((WORK/'code_novelty_audit.json').read_text());shutil.copy2(WORK/'code_novelty_audit.json',OUT/'prior_code_audit.json')
    source_paths=['research/reports/sector_championship_20261005.md','research/runners/sector_championship_20261005.py']
    sources={}
    for p in source_paths:
        data=subprocess.run(['git','show','research-archive-before-cleanup-20261101:'+p],capture_output=True)
        if data.returncode==0:sources[p]=dict(sha256=hashlib.sha256(data.stdout).hexdigest(),residual_lines=[s for s in data.stdout.decode(errors='replace').splitlines() if 'residual momentum' in s.lower()])
    for p in (WORK/'archive_sources').glob('*.py'):sources[p.name]=dict(sha256=hashlib.sha256(p.read_bytes()).hexdigest(),role='archived evaluator or imported watchdog, no main execution')
    (OUT/'archive_receipts.json').write_text(json.dumps(sources,indent=2),encoding='utf-8')
    names=list(summary.index);rows=[]
    for name in names:
        r=summary.loc[name];p=pairs[pairs.model.eq(name)&pairs.policy.eq('global_top20')].iloc[0]
        rows.append(dict(model=name,rank_ic=r.rank_ic,ic_delta=r.rank_ic-base.rank_ic,professor_gain=100*(r.alignment-base.alignment),high_gain=100*(r.raw_high_percentile-base.raw_high_percentile),goal_delta=100*(r.top3_goal_hit-base.top3_goal_hit),xirr_delta=100*p.xirr_delta,dd_delta=100*p.drawdown_delta,changed=100*r.changed,portfolio_dates=p.matched_dates))
    compact=pd.DataFrame(rows);compact.to_csv(OUT/'comparison.csv',index=False)
    fig,axes=plt.subplots(1,3,figsize=(13,4.8));colors=['#444444','#2166ac','#b2182b','#1b7837']
    axes[0].barh(names,compact.rank_ic,color=colors);axes[0].set_title('Within-sector rank IC');axes[0].axvline(0,color='grey',lw=.7)
    axes[1].barh(names,compact.professor_gain,color=colors);axes[1].set_title('Professor alignment gain (pp)');axes[1].axvline(0,color='grey',lw=.7)
    axes[2].barh(names,compact.xirr_delta,color=colors);axes[2].set_title('Matched Top20 SIP XIRR gain (pp)');axes[2].axvline(0,color='grey',lw=.7)
    for ax in axes[1:]:ax.set_yticklabels([])
    fig.suptitle('New residual-history pilot | Development 2020–2023 | 100bp per side',fontsize=13);fig.tight_layout(rect=[0,0,1,.93])
    plot=ROOT/'research/reports/residual_challengers_20261105.png';fig.savefig(plot,dpi=150);plt.close(fig)
    text=['# Residual-history champion search, 5 November 2026','',f"Development nomination: **{', '.join(decision['development_nominees']) or 'none'}**. Three new feature policies were evaluated. The existing champion remains the reference.",'','## Novelty audit','','The saved archive contains 146 report/protocol paths. Archived runner code revealed earlier monotonic tree models, so the initially proposed monotonic family was dropped before fitting. Raw recency, trend smoothness, factor-weight sweeps, recovery, generic momentum and prior model tournaments were also excluded. Earlier reports explicitly state that their sector percentiles were not regression residual momentum. This supports novelty relative to saved evidence, with uncertainty for uncatalogued manual trials.','',f"The persistent incomplete registry now has {decision['documented_attempts']} documented attempts. This round adds three policies, with no model fitting or hyperparameter search. The local scoped multiplicity calculation covers these three policies only and cannot repair earlier adaptive reuse.",'','## Method and professor alignment','','Weekly log returns are regressed on an intercept plus leave-one-out market and sector reference returns over156weeks. Momentum uses the48residual weeks ending4weeks before the snapshot, normalized by residual volatility. The second feature measures time since the maximum cumulative residual over48weeks. These features test stock-specific behavior after common movements are removed. Reference baskets and sectors come from the current-survivor historical cohort. They are not certified point-in-time investable market factors.','','- residual_momentum20 uses80%champion and20%residual-momentum percentile.','- professor_residual50 uses30%champion,50%equal five-block professor core and20%residual momentum.','- residual_high20 uses80%champion and20%residual-path high-recency percentile.','','Only professor_residual50 guarantees50%explicit professor score mass. The other policies must preserve measured professor and raw-high alignment to pass. The workbook does not prescribe these coefficients. Inputs inherit five-year complete-factor eligibility, so younger listings are outside this pilot. The champion and all challengers use exactly the same reduced feature cohorts, with sector normalization before label filtering.','','## Matched development results','','| Policy | IC | IC delta | Professor alignment gain pp | Raw high alignment gain pp | Goal hit delta pp | Top20 XIRR delta pp | Top20 DD delta pp | Changed Top3 % | Portfolio dates |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
    for r in rows:text.append(f"| {r['model']} | {r['rank_ic']:.5f} | {r['ic_delta']:+.5f} | {r['professor_gain']:+.2f} | {r['high_gain']:+.2f} | {r['goal_delta']:+.2f} | {r['xirr_delta']:+.2f} | {r['dd_delta']:+.2f} | {r['changed']:.1f} | {r['portfolio_dates']} |")
    text+=['','Positive DD delta means less severe drawdown. RankIC is date-balanced mean sector Spearman correlation with corrected12monthSIPXIRR, not market-index alpha. GlobalTop20 compares within-sector normalized scores across sectors. Joint complete sectorTop3 queries are common across policies, portfolio pair date support can differ. Actual adjusted next-open buys,100bp per side, fractional units, price-only outcomes and unresolved-action blocks remain the existing execution proxy. See blocked/failure and annual CSVs. The reference champion IC differs slightly from earlier reports because this round uses the smaller common residual-feature cohort.','',f"The fixed incremental IC floor is0.010134924. This round’s95%familywise365day-block bootstrap hurdle is{decision['familywise_ic_hurdle']:.5f}. Both are required, alongside IC gain in3of4years, nonworsening professor/high alignment and goal hit, positive portfolio return gain robust to10%winsorization and every leave-one-date-out deletion, drawdown worsening<=2pp and adequate support.",'','## Individual decisions','']
    for d in decision['candidates']:
        failed=[k for k,v in d['checks'].items() if not v]
        text.append(f"- **{d['model']}**. Positive IC years {d['positive_years']}/4. Winsorized portfolio delta {100*d['winsor_xirr_delta']:+.2f}pp, worst leave-one-date-out {100*d['worst_lodo_xirr_delta']:+.2f}pp. Failed requirements: {', '.join(failed) or 'none'}.")
    text+=['','## Verification and limits','',f"Four residual-feature tests passed. They check prefix invariance, self-exclusion, missing-history handling and a known idiosyncratic trend. {decision['rows']:,} stock-date rows across{decision['dates']} development dates were scored. Input, protocol and archive-code hashes are retained. The prior registry IDs remain present. Exposed2024–2025 was not evaluated. The data were already used for many development decisions, and sixteen overlapping cohorts do not supply independent validation. No current/live ranking or website/runtime change is produced. The October3runtime remains stale for the prospective holdout.",'','## Literature and implementation review','','Scite returned paper metadata, full-text excerpts and citation context. No editorial-notice fields appeared in the returned records, so absence of notices is not independent certification. GitHub inspection found a homework reproduction usingFF5andChina data, whose README warns of possible mistakes. No implementation was copied or executed. Continuity/Frog-in-the-Pan work was excluded from this pilot because earlier project proxies already target that idea.','','References','','- Blitz, D. C., Huij, J., & Martens, M. (2011). Residual momentum. *Journal of Empirical Finance,18*(3),506–521. https://doi.org/10.1016/j.jempfin.2011.01.003. Primary inspiration for regressing out common returns. Our market/sector weekly adaptation differs from the paper’s Fama–French factors.','- Da, Z., Gurun, U. G., & Warachka, M. (2014). Frog in the pan: Continuous information and momentum. *Review of Financial Studies,27*(7),2171–2218. https://doi.org/10.1093/rfs/hhu003. Reviewed and excluded as substantially overlapping prior continuity tests.','- Jansen, M., Swinkels, L., & Zhou, W. (2021). Anomalies in the China A-share market. Working paper. https://doi.org/10.2139/ssrn.3810114. Scite full-text reports residual-momentum tests in China, supporting cross-market investigation but not Indian performance.','- Singh, S., Walia, N., & Bekiros, S. D. (2022). Risk-managed time-series momentum: An emerging economy experience. *Journal of Economics, Finance and Administrative Science,27*(54),328–343. https://doi.org/10.1108/JEFAS-08-2021-0159. Indian-market context, not validation of this estimator.','- dexin-peng. (2022). Residual momentum toy reproduction. https://github.com/dexin-peng/Blitz-et-al.-2011-Residual-Momentum-toy-reproduce. Reference lead only.']
    report=ROOT/'research/reports/residual_challengers_20261105.md';report.write_text('\n'.join(text)+'\n',encoding='utf-8',newline='\n')
    dest=Path('C:/Users/Harshil/Documents/Codex/2026-10-31/you/outputs')
    for p in [report,plot]:shutil.copy2(p,dest/p.name)
    artifacts=[p for p in OUT.iterdir() if p.is_file() and p.name!='manifest.json']+[report,plot,ROOT/'research/protocols/residual_challengers_20261105.md',ROOT/'research/research_variant_ledger.csv',ROOT/'src/stock_research/residual_history.py',ROOT/'research/runners/residual_challengers_20261105.py',ROOT/'research/runners/residual_review_20261105.py']
    (OUT/'manifest.json').write_text(json.dumps([dict(path=p.relative_to(ROOT).as_posix(),sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for p in artifacts],indent=2),encoding='utf-8')
    print(compact.to_string(index=False),flush=True)


if __name__=='__main__':main()
